// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address payer, address querier, uint256 amount) public {
        vm.assume(payer != address(0));
        vm.assume(querier != address(0));
        amount = bound(amount, 0, 1 ether);

        vm.deal(payer, amount);
        vm.prank(payer);
        c.addToBalance{value: amount}();

        uint balFromView;
        vm.prank(querier);
        balFromView = c.getBalance(payer);

        vm.prank(payer);
        uint balWhenQueriedByOwner = c.getBalance(payer);

        assertTrue(balFromView == balWhenQueriedByOwner);
    }
}
